<?php

namespace Database\Seeders;

use App\Models\Content\Lesson;
use App\Models\Content\LessonContent;
use App\Models\Exercise\Exercise;
use App\Models\Exercise\ExerciseQuestion;
use App\Models\System\Level;
use App\Models\Test\Test;
use App\Models\Test\TestAnswer;
use App\Models\Test\TestQuestion;
use App\Models\Vocabulary\Word;
use App\Models\Vocabulary\WordTranslation;
use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;

/**
 * Generates full-standard lessons (content + vocabulary + exercises + test)
 * from compact topic definitions. Idempotent: safe to re-run, only fills
 * in whatever is missing for each topic/lesson.
 */
class BulkLessonSeeder extends Seeder
{
    /** @var array<string,int> */
    private array $levelIds = [];

    /** @var string[] */
    private array $fallbackDistractors = [
        'дом', 'время', 'вопрос', 'работа', 'друг', 'вода', 'день', 'город',
        'история', 'идея', 'дорога', 'книга', 'окно', 'дверь', 'стол',
    ];

    private array $report = ['lessons' => 0, 'words' => 0, 'exercises' => 0, 'questions' => 0, 'tests' => 0, 'errors' => []];

    public function run(): void
    {
        $this->levelIds = Level::pluck('id', 'code')->all();

        foreach ($this->topics() as $topic) {
            $this->buildLessonFromTopic($topic);
        }

        $this->command?->info(sprintf(
            class_basename(static::class).': +%d lessons, +%d words, +%d exercises, +%d questions, +%d tests',
            $this->report['lessons'],
            $this->report['words'],
            $this->report['exercises'],
            $this->report['questions'],
            $this->report['tests']
        ));

        foreach ($this->report['errors'] as $error) {
            $this->command?->error($error);
        }
    }

    private function buildLessonFromTopic(array $topic): void
    {
        try {
            DB::transaction(function () use ($topic) {
                $levelId = $this->levelIds[$topic['level']] ?? null;

                if (! $levelId) {
                    throw new \RuntimeException("Unknown level code: {$topic['level']}");
                }

                $lesson = Lesson::where('level_id', $levelId)->where('title', $topic['title'])->first();

                if (! $lesson) {
                    $lesson = Lesson::create([
                        'level_id' => $levelId,
                        'title' => $topic['title'],
                        'description' => $topic['intro'],
                        'order_number' => (int) (Lesson::where('level_id', $levelId)->max('order_number') ?? 0) + 1,
                        'estimated_minutes' => $topic['minutes'] ?? 30,
                        'is_published' => true,
                    ]);
                    $this->report['lessons']++;
                }

                $this->ensureContent($lesson, $topic);
                $this->ensureVocabulary($lesson, $topic);
                $this->ensureExercises($lesson, $topic);
                $this->ensureTest($lesson, $topic);
            });
        } catch (\Throwable $e) {
            $this->report['errors'][] = "{$topic['title']}: {$e->getMessage()}";
        }
    }

    private function ensureContent(Lesson $lesson, array $topic): void
    {
        $hasGoodContent = LessonContent::where('lesson_id', $lesson->id)
            ->where('type', 'text')
            ->get()
            ->contains(fn ($c) => strlen(strip_tags($c->content ?? '')) > 400);

        if ($hasGoodContent) {
            return;
        }

        LessonContent::where('lesson_id', $lesson->id)->where('type', 'text')->delete();

        LessonContent::create([
            'lesson_id' => $lesson->id,
            'type' => 'text',
            'title' => $topic['title'],
            'content' => $this->buildContentHtml($topic),
            'order_number' => 1,
        ]);
    }

    private function buildContentHtml(array $topic): string
    {
        $e = fn ($s) => e($s);

        $html = '<h2>Introduction</h2>';
        $html .= '<p>'.$e($topic['intro']).'</p>';

        $html .= '<h2>The Rule</h2>';
        $html .= '<p>'.$e($topic['rule_explanation']).'</p>';
        $html .= '<p><strong>Formula:</strong> '.$e($topic['formula']).'</p>';

        $html .= '<h2>Examples</h2><table><tr><th>Affirmative</th><th>Negative</th><th>Question</th></tr>';
        $rows = max(count($topic['examples']['affirmative']), count($topic['examples']['negative']), count($topic['examples']['questions']));
        for ($i = 0; $i < $rows; $i++) {
            $aff = $topic['examples']['affirmative'][$i][0] ?? '';
            $neg = $topic['examples']['negative'][$i][0] ?? '';
            $q = $topic['examples']['questions'][$i][0] ?? '';
            $html .= '<tr><td>'.$e($aff).'</td><td>'.$e($neg).'</td><td>'.$e($q).'</td></tr>';
        }
        $html .= '</table>';

        $html .= '<h2>More Examples</h2><ul>';
        foreach ($topic['more'] as $sentence) {
            $html .= '<li>'.$e($sentence).'</li>';
        }
        $html .= '</ul>';

        $html .= '<h2>Common Mistakes</h2><ul>';
        foreach ($topic['mistakes'] as $m) {
            $html .= '<li>&#10060; '.$e($m['wrong']).'<br>&#9989; '.$e($m['right']).'</li>';
        }
        $html .= '</ul>';

        $html .= '<h2>Exceptions &amp; Nuances</h2><ul>';
        foreach ($topic['exceptions'] as $item) {
            $html .= '<li>'.$e($item).'</li>';
        }
        $html .= '</ul>';

        $html .= '<h2>Summary</h2><ul>';
        foreach ($topic['summary'] as $item) {
            $html .= '<li>'.$e($item).'</li>';
        }
        $html .= '</ul>';

        return $html;
    }

    private function ensureVocabulary(Lesson $lesson, array $topic): void
    {
        $existing = Word::where('lesson_id', $lesson->id)->pluck('id', 'word');

        foreach ($topic['vocab'] as $v) {
            if (isset($existing[$v['word']])) {
                continue;
            }

            $word = Word::create([
                'lesson_id' => $lesson->id,
                'word' => $v['word'],
                'transcription' => $v['transcription'],
                'example' => $v['example'],
                'difficulty' => $this->difficultyForLevel($topic['level']),
            ]);

            WordTranslation::create([
                'word_id' => $word->id,
                'language' => 'ru',
                'translation' => $v['ru'],
                'definition' => null,
                'example' => $v['example'],
            ]);

            $this->report['words']++;
        }
    }

    private function ensureExercises(Lesson $lesson, array $topic): void
    {
        $existingTypes = Exercise::where('lesson_id', $lesson->id)->pluck('type')->all();

        if (! in_array('fill_blank', $existingTypes, true)) {
            $exercise = Exercise::create([
                'lesson_id' => $lesson->id,
                'title' => 'Fill in the Blanks: '.$topic['title'],
                'type' => 'fill_blank',
                'instructions' => 'Complete each sentence with the correct word.',
            ]);
            $this->report['exercises']++;

            foreach (['affirmative', 'negative', 'questions'] as $group) {
                foreach ($topic['examples'][$group] as [$sentence, $key]) {
                    $blanked = preg_replace('/\b'.preg_quote($key, '/').'\b/i', '_____', $sentence, 1);
                    ExerciseQuestion::create([
                        'exercise_id' => $exercise->id,
                        'question' => $blanked,
                        'correct_answer' => $key,
                    ]);
                    $this->report['questions']++;
                }
            }
        }

        if (! in_array('translation', $existingTypes, true)) {
            $exercise = Exercise::create([
                'lesson_id' => $lesson->id,
                'title' => 'Translate the Words: '.$topic['title'],
                'type' => 'translation',
                'instructions' => 'Translate each English word into Russian.',
            ]);
            $this->report['exercises']++;

            foreach ($topic['vocab'] as $v) {
                ExerciseQuestion::create([
                    'exercise_id' => $exercise->id,
                    'question' => $v['word'],
                    'correct_answer' => $v['ru'],
                ]);
                $this->report['questions']++;
            }
        }

        if (! in_array('matching', $existingTypes, true)) {
            $exercise = Exercise::create([
                'lesson_id' => $lesson->id,
                'title' => 'Match the Word to Its Example: '.$topic['title'],
                'type' => 'matching',
                'instructions' => 'Match each word to the sentence that uses it correctly.',
            ]);
            $this->report['exercises']++;

            foreach ($topic['vocab'] as $v) {
                ExerciseQuestion::create([
                    'exercise_id' => $exercise->id,
                    'question' => $v['word'],
                    'correct_answer' => $v['example'],
                ]);
                $this->report['questions']++;
            }
        }
    }

    private function ensureTest(Lesson $lesson, array $topic): void
    {
        if (Test::where('lesson_id', $lesson->id)->exists()) {
            return;
        }

        $test = Test::create([
            'lesson_id' => $lesson->id,
            'title' => 'Test: '.$topic['title'],
            'passing_score' => 75,
            'time_limit' => 12,
            'is_published' => true,
        ]);
        $this->report['tests']++;

        foreach ($topic['test_grammar'] as $tg) {
            $question = TestQuestion::create([
                'test_id' => $test->id,
                'question' => $tg['q'],
                'type' => 'single_choice',
                'points' => 1,
            ]);
            $this->storeAnswers($question->id, $tg['correct'], $tg['wrong']);
            $this->report['questions']++;
        }

        $vocabSample = array_slice($topic['vocab'], 0, min(5, count($topic['vocab'])));
        foreach ($vocabSample as $v) {
            $others = collect($topic['vocab'])
                ->reject(fn ($x) => $x['word'] === $v['word'])
                ->pluck('ru')
                ->unique()
                ->shuffle();

            if ($others->count() < 3) {
                $others = $others->concat(collect($this->fallbackDistractors)->shuffle())->unique();
            }

            $others = $others->take(3);

            $question = TestQuestion::create([
                'test_id' => $test->id,
                'question' => "What does '{$v['word']}' mean?",
                'type' => 'single_choice',
                'points' => 1,
            ]);
            $this->storeAnswers($question->id, $v['ru'], $others->all());
            $this->report['questions']++;
        }
    }

    /**
     * Сохраняет варианты ответа в перемешанном порядке.
     *
     * Раньше правильный вставлялся первым, а варианты показывались в порядке
     * id — в итоге ответом почти всегда был вариант А, и тест проходился
     * угадыванием. Позиция задаётся sort_order, id при этом не трогаются:
     * на них ссылаются попытки учеников.
     *
     * @param  array<int, string>  $wrong
     */
    private function storeAnswers(int $questionId, string $correct, array $wrong): void
    {
        $options = array_merge([[$correct, true]], array_map(fn ($text) => [$text, false], $wrong));
        shuffle($options);

        foreach ($options as $position => [$text, $isCorrect]) {
            TestAnswer::create([
                'question_id' => $questionId,
                'answer' => $text,
                'is_correct' => $isCorrect,
                'sort_order' => $position,
            ]);
        }
    }

    private function difficultyForLevel(string $level): int
    {
        return match ($level) {
            'A1' => random_int(1, 3),
            'A2' => random_int(3, 5),
            'B1' => random_int(5, 7),
            'B2' => random_int(7, 8),
            'C1' => random_int(8, 10),
            default => 5,
        };
    }

    /**
     * @return array<int, array<string, mixed>>
     */
    /** @return array<int, array<string, mixed>> */
    protected function topics(): array
    {
        return array_merge(
            $this->topicsA1(),
            $this->topicsA1b(),
            $this->topicsA1c(),
            $this->topicsA2(),
            $this->topicsA2b(),
            $this->topicsB1(),
            $this->topicsB1b(),
            $this->topicsB2(),
            $this->topicsB2b(),
            $this->topicsC1(),
            $this->topicsC1b(),
            $this->topicsC1c(),
        );
    }

