                'rule_explanation' => 'A possessive adjective always comes before a noun and never changes form, no matter if the noun is singular or plural.',
                'examples' => [
                    'affirmative' => [
                        ['This is my house.', 'my'],
                        ['Is that your book?', 'your'],
                        ['Her name is Sara.', 'Her'],
                        ['Their car is new.', 'Their'],
                    ],
                    'negative' => [
                        ["This isn't my bag.", 'my'],
                        ["That isn't your phone.", 'your'],
                        ["This isn't his coat.", 'his'],
                        ["That isn't their house.", 'their'],
                    ],
                    'questions' => [
                        ['Is this your umbrella?', 'your'],
                        ['Is that his car?', 'his'],
                        ['What is her job?', 'her'],
                        ['Where is their office?', 'their'],
                    ],
                ],
                'more' => [
                    'Our teacher is very patient.',
                    'The cat likes its food.',
                    'His sister lives in Tashkent.',
                    'My parents live in the countryside.',
                    'Your English is improving fast.',
                    'Her office is on the second floor.',
                    'Their children go to the same school.',
                    'Its color is dark blue.',
                ],
                'mistakes' => [
                    ['wrong' => 'This is my\'s house.', 'right' => 'This is my house.'],
                    ['wrong' => 'Her is a doctor.', 'right' => 'She is a doctor.'],
                    ['wrong' => 'The dog likes it\'s food.', 'right' => 'The dog likes its food.'],
                    ['wrong' => 'This is hers book.', 'right' => 'This is her book.'],
                ],
                'exceptions' => [
                    '"Its" (possessive) has no apostrophe; "it\'s" means "it is".',
                    'Possessive adjectives never take -s: not "hers house", but "her house".',
                    'Don\'t confuse "her" (adjective, before noun) with "hers" (pronoun, no noun after).',
                ],
                'summary' => [
                    'Possessive adjectives go before a noun.',
                    'They never change form for plural nouns.',
                    'Its = possessive; it\'s = it is.',
                    'Learn my/your/his/her/its/our/their together.',
                ],
                'vocab' => [
                    ['word' => 'house', 'transcription' => 'haʊs', 'ru' => 'дом', 'example' => 'This is my house.'],
                    ['word' => 'umbrella', 'transcription' => 'ʌmˈbrelə', 'ru' => 'зонт', 'example' => 'Is this your umbrella?'],
                    ['word' => 'coat', 'transcription' => 'kəʊt', 'ru' => 'пальто', 'example' => "That isn't his coat."],
