                    ['word' => 'patient', 'transcription' => 'ˈpeɪʃnt', 'ru' => 'терпеливый', 'example' => 'Our teacher is very patient.'],
                    ['word' => 'color', 'transcription' => 'ˈkʌlər', 'ru' => 'цвет', 'example' => 'Its color is dark blue.'],
                    ['word' => 'job', 'transcription' => 'dʒɒb', 'ru' => 'работа', 'example' => 'What is her job?'],
                    ['word' => 'children', 'transcription' => 'ˈtʃɪldrən', 'ru' => 'дети', 'example' => 'Their children go to the same school.'],
                ],
                'test_grammar' => [
